struct DSU {
    vector<int> parent;
    vector<int> sz;

    DSU(int n) {
        parent.resize(n + 1);
        iota(parent.begin(), parent.end(), 0);
        sz.assign(n + 1, 1);
    }

    int find(int i) {
        if (parent[i] == i)
            return i;
        return parent[i] = find(parent[i]);
    }

    void unite(int i, int j) {
        int ri = find(i);
        int rj = find(j);
        if (ri != rj) {
            if (sz[ri] < sz[rj])
                swap(ri, rj);
            parent[rj] = ri;
            sz[ri] += sz[rj];
        }
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);

    int n;
    cin >> n;

    vector<int> a(n + 1);
    for (int i = 1; i <= n; i++) {
        cin >> a[i];
    }

    vector<vector<int>> adj(n + 1);
    for (int i = 0; i < n - 1; i++) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    vector<int> order(n);
    iota(order.begin(), order.end(), 1);
    sort(order.begin(), order.end(), [&](int u, int v) {
        return a[u] < a[v];
    });

    DSU max_(n);
    vector<bool> active(n + 1, false);
    long long ans = 0;

    for (int u : order) {
        active[u] = true;
        for (int v : adj[u]) {
            if (active[v]) {
                int ru = max_.find(u);
                int rv = max_.find(v);
                if (ru != rv) {
                    ans += 1LL * a[u] * max_.sz[ru] * max_.sz[rv];
                    max_.unite(ru, rv);
                }
            }
        }
    }
    sort(order.begin(), order.end(), [&](int u, int v) {
        return a[u] > a[v];
    });

    DSU min_(n);
    fill(active.begin(), active.end(), false);
    long long res = 0;

    for (int u : order) {
        active[u] = true;
        for (int v : adj[u]) {
            if (active[v]) {
                int ru = min_.find(u);
                int rv = min_.find(v);
                if (ru != rv) {
                    res += 1LL * a[u] * min_.sz[ru] * min_.sz[rv];
                    min_.unite(ru, rv);
                }
            }
        }
    }

    cout << ans - res << "\n";
}